#include "ej-20-54-framework-de-fsm.h"
bool fsm_inicializar(maquina_estados_t*m,estado_fsm_e e,void*c){if(!m||(unsigned)e>=FSM_ESTADO_MAX)return false;m->estado_actual=e;m->num_transiciones=0;m->contexto=c;return true;}
bool fsm_agregar_transicion(maquina_estados_t*m,transicion_t t){if(!m||m->num_transiciones<0||m->num_transiciones>=64||(unsigned)t.desde>=FSM_ESTADO_MAX||(unsigned)t.hasta>=FSM_ESTADO_MAX||(unsigned)t.evento>=FSM_EVENTO_MAX)return false;m->transiciones[m->num_transiciones++]=t;return true;}
bool fsm_procesar(maquina_estados_t*m,evento_fsm_e e){if(!m||(unsigned)e>=FSM_EVENTO_MAX)return false;for(int i=0;i<m->num_transiciones;i++){transicion_t*t=&m->transiciones[i];if(t->desde==m->estado_actual&&t->evento==e){if(t->accion)t->accion(m->contexto);m->estado_actual=t->hasta;return true;}}return false;}
